static void handle_PORT(ctrl_t *ctrl, char *str)
{
	int a, b, c, d, e, f;
	char addr[INET_ADDRSTRLEN];
	struct sockaddr_in sin;

	if (ctrl->data_sd > 0) {
		uev_io_stop(&ctrl->data_watcher);
		close(ctrl->data_sd);
		ctrl->data_sd = -1;
	}

	/* Convert PORT command's argument to IP address + port */
	sscanf(str, "%d,%d,%d,%d,%d,%d", &a, &b, &c, &d, &e, &f);
	sprintf(addr, "%d.%d.%d.%d", a, b, c, d);

	/* Check IPv4 address using inet_aton(), throw away converted result */
	if (!inet_aton(addr, &(sin.sin_addr))) {
		ERR(0, "Invalid address '%s' given to PORT command", addr);
		send_msg(ctrl->sd, "500 Illegal PORT command.\r\n");
		return;
	}

	strlcpy(ctrl->data_address, addr, sizeof(ctrl->data_address));
	ctrl->data_port = e * 256 + f;

	DBG("Client PORT command accepted for %s:%d", ctrl->data_address, ctrl->data_port);
	send_msg(ctrl->sd, "200 PORT command successful.\r\n");
}

@Override
protected void doPost(HttpServletRequest req, HttpServletResponse resp)
		throws ServletException, IOException {

	// Nome dos usuario pesquisado
	String name = req.getParameter("name");

	String query = "SELECT * FROM USER WHERE NAME = '" + name + "'";
	ResultSet users = Database.execute(query);

	ArrayList<User> searchedUsers = new ArrayList<User>();
	try {

		while (users.next()){
			searchedUsers.add(new User(users.getString(1),users.getString(2),users.getString(3)));
		}

		Gson gson = new Gson();
		ServletOutputStream os = resp.getOutputStream();

		os.print(gson.toJson(searchedUsers));
		os.flush();
		os.close();

	} catch (SQLException e) {
		e.printStackTrace();
	}	

}

[HttpGet("General/{name}/{type}")]
[AllowAnonymous]
[Produces(MediaTypeNames.Application.Octet)]
[ProducesResponseType(StatusCodes.Status200OK)]
[ProducesResponseType(StatusCodes.Status404NotFound)]
[ProducesImageFile]
public ActionResult GetGeneralImage([FromRoute, Required] string name, [FromRoute, Required] string type)
{
    var filename = string.Equals(type, "primary", StringComparison.OrdinalIgnoreCase)
        ? "folder"
        : type;

    var path = BaseItem.SupportedImageExtensions
        .Select(i => Path.Combine(_applicationPaths.GeneralPath, name, filename + i))
        .FirstOrDefault(System.IO.File.Exists);

    if (path == null)
    {
        return NotFound();
    }

    var contentType = MimeTypes.GetMimeType(path);
    return File(System.IO.File.OpenRead(path), contentType);
}

function embedVimeoIframe(e){
	var elem = e.currentTarget;
	var id = elem.getAttribute('data-vimeo');
	var vimeoParams = elem.getAttribute('data-vimeoparams') || '';

	if(vimeoParams && !regAmp.test(vimeoParams)){
		vimeoParams = '&'+ vimeoParams;
	}

	e.preventDefault();

	elem.innerHTML = '<iframe src="' + (vimeoIframe.replace(regId, id)) + vimeoParams +'" ' +
		'frameborder="0" allowfullscreen="" width="640" height="390"></iframe>'
	;

	elem.removeEventListener('click', embedVimeoIframe);
}

const char*  wolfSSL_CIPHER_get_version(const WOLFSSL_CIPHER* cipher)
{
